<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {onShow,onHide} from '@dcloudio/uni-app'
import {maintenance} from '../lib/maintenance'
import ClientDialog from './ClientDialog.vue'
import {isH5} from '../lib/api'
import {maintenancePresentation} from '@qicore/application-sdk/browser/maintenance-client.mjs'
const state=ref<any>({active:false}),retrying=ref(false),visible=ref(true)
const notice=computed(()=>maintenancePresentation(state.value)),icon=computed(()=>(isH5?'/h5-assets':'')+'/static/decoration/framework/icons/'+(notice.value.attention?'settings-blue':'refresh-cw-blue')+'.svg')
let release:(()=>unknown)|undefined
function watch(){if(!release)release=maintenance.subscribe(value=>state.value=value)}
function stop(){release?.();release=undefined}
function visibility(){if(typeof document!=='undefined'&&document.visibilityState==='hidden')stop();else watch()}
async function retry(){if(retrying.value)return;retrying.value=true;try{await maintenance.retry()}finally{retrying.value=false}}
onMounted(()=>{visibility();if(typeof document!=='undefined')document.addEventListener('visibilitychange',visibility)});onShow(()=>{visible.value=true;visibility()});onHide(()=>{visible.value=false;stop()});onBeforeUnmount(()=>{stop();if(typeof document!=='undefined')document.removeEventListener('visibilitychange',visibility)})
</script>
<template><ClientDialog class="maintenance-modal" v-if="state.active&&visible" :title="notice.title" persistent blur-backdrop><view class="maintenance-notice" :class="{attention:notice.attention}" role="status" aria-live="polite"><view class="maintenance-header"><view class="maintenance-icon"><image class="maintenance-icon-image" :src="icon" mode="aspectFit" aria-hidden="true"/></view><view class="maintenance-copy"><view class="maintenance-title-row"><text class="maintenance-title">{{notice.title}}</text><text v-if="notice.estimate" class="maintenance-estimate">{{notice.estimate}}</text></view><text class="maintenance-description">{{notice.description}}</text></view></view><view class="maintenance-footer"><view class="maintenance-hint"><view class="maintenance-dot"/><text>{{notice.hint}}</text></view><button class="maintenance-retry" role="button" tabindex="0" aria-label="检查恢复状态" :aria-busy="retrying" :loading="retrying" :disabled="retrying" @click="retry" @keydown.enter.prevent="retry" @keydown.space.prevent="retry">{{retrying?'检查中':'检查状态'}}</button></view></view></ClientDialog></template>
<style scoped>
.maintenance-modal :deep(.client-dialog-panel){max-width:336px;border-radius:14px}.maintenance-modal :deep(.client-dialog-header),.maintenance-modal :deep(.client-dialog-footer){display:none}.maintenance-modal :deep(.client-dialog-body){padding:0;max-height:calc(100dvh - 32px)}
.maintenance-notice{box-sizing:border-box;padding:16px;background:var(--client-surface,#fff);color:var(--client-text,#253348);font:12px/1.65 -apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif}.maintenance-header{display:flex;align-items:flex-start;gap:10px}.maintenance-icon{display:flex;align-items:center;justify-content:center;flex:none;width:34px;height:34px;border-radius:10px;background:var(--client-primary-soft,#edf4ff)}.maintenance-icon .maintenance-icon-image{width:19px;height:19px}.maintenance-copy{flex:1;min-width:0}.maintenance-title-row{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:4px 6px}.maintenance-title{font-size:14px;line-height:1.5;font-weight:650;color:var(--client-text,#253348)}.maintenance-estimate{flex:none;padding:2px 7px;border-radius:999px;background:var(--client-primary-soft,#edf4ff);color:var(--client-primary,#2563eb);font-size:10px;line-height:1.5}.maintenance-description{display:block;margin-top:4px;color:var(--client-muted,#79879b);font-size:11.5px;line-height:1.6;overflow-wrap:anywhere}.maintenance-footer{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:13px;padding-top:12px;border-top:1px solid #edf0f5}.maintenance-hint{display:flex;align-items:flex-start;gap:5px;flex:1;min-width:0;color:var(--client-muted,#8a94a1);font-size:10.5px;line-height:1.6}.maintenance-dot{flex:none;width:4px;height:4px;margin-top:6px;border-radius:50%;background:var(--client-primary,#2563eb);opacity:.55}.maintenance-retry{display:flex;align-items:center;justify-content:center;flex:none;width:auto;min-width:76px;height:31px;margin:0;padding:0 11px;border:0;border-radius:7px;background:var(--client-primary-soft,#edf4ff);color:var(--client-primary,#2563eb);font:550 12px/1.4 -apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif}.maintenance-retry::after{border:0}.attention .maintenance-icon,.attention .maintenance-retry{background:#f2f5f9}.attention .maintenance-dot{background:#9aa4b2}
</style>
